const output = $('Research Competitor Reviews').first().json.output;
const competitor = $('Loop Over Competitors').first().json.Competitor;
const weekOf = new Date().toISOString().slice(0, 10);
const positives = (output.positiveReviews || []).map(r => ({
  Competitor: competitor, Sentiment: 'Positive', Source: r.source, ReviewSnippet: r.snippet, WeekOf: weekOf
}));
const negatives = (output.negativeReviews || []).map(r => ({
  Competitor: competitor, Sentiment: 'Negative', Source: r.source, ReviewSnippet: r.snippet, WeekOf: weekOf
}));
const all = [...positives, ...negatives];
if (all.length === 0) {
  all.push({ Competitor: competitor, Sentiment: 'No review found', Source: 'No review found', ReviewSnippet: 'No review found', WeekOf: weekOf });
}
return all.map(r => ({ json: r }));
